#!/usr/bin/env python3
"""Interactive Linux controller mapping support for the PuddleDuck web UI.

The editor opens the exact device named by one controller YAML definition,
observes raw Linux joystick/evdev input events, and reports button presses or
the dominant axis in one movement gesture.  YAML edits are applied with
PyYAML node marks so existing comments and surrounding formatting are retained.
"""

from __future__ import annotations

import array
import fcntl
import json
import os
import secrets
import struct
import threading
import time
from collections import deque
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Deque, Dict, Iterable, List, Mapping, Optional, Tuple

import yaml
from yaml.nodes import MappingNode, ScalarNode, SequenceNode


JSIOCGNAME = 0x80006A13
JS_EVENT_BUTTON = 0x01
JS_EVENT_AXIS = 0x02
JS_EVENT_INIT = 0x80
EV_KEY = 0x01
EV_ABS = 0x03

_JS_EVENT = struct.Struct("IhBB")
_INPUT_EVENT = struct.Struct("@llHHi")

_IOC_NRBITS = 8
_IOC_TYPEBITS = 8
_IOC_SIZEBITS = 14
_IOC_DIRBITS = 2
_IOC_NRSHIFT = 0
_IOC_TYPESHIFT = _IOC_NRSHIFT + _IOC_NRBITS
_IOC_SIZESHIFT = _IOC_TYPESHIFT + _IOC_TYPEBITS
_IOC_DIRSHIFT = _IOC_SIZESHIFT + _IOC_SIZEBITS
_IOC_READ = 2
_ABSINFO = struct.Struct("iiiiii")


def _IOC(direction: int, typ: str, nr: int, size: int) -> int:
    return (
        (direction << _IOC_DIRSHIFT)
        | (ord(typ) << _IOC_TYPESHIFT)
        | (nr << _IOC_NRSHIFT)
        | (size << _IOC_SIZESHIFT)
    )


def _EVIOCGABS(code: int) -> int:
    return _IOC(_IOC_READ, "E", 0x40 + int(code), _ABSINFO.size)


def _normalise_device_name(value: Any) -> str:
    return " ".join(str(value or "").split()).casefold()


def _js_device_name(path: Path) -> str:
    fd = os.open(path, os.O_RDONLY | os.O_NONBLOCK)
    try:
        buf = array.array("b", [0] * 256)
        fcntl.ioctl(fd, JSIOCGNAME + (len(buf) << 16), buf)
        return buf.tobytes().rstrip(b"\x00").decode("utf-8", "replace").strip()
    finally:
        os.close(fd)


def _event_device_name(path: Path, sysfs_root: Path) -> str:
    name_path = sysfs_root / path.name / "device" / "name"
    return name_path.read_text(encoding="utf-8").strip()


def find_controller_device(
    device_name: str,
    *,
    input_root: Path | str = "/dev/input",
    sysfs_root: Path | str = "/sys/class/input",
) -> Tuple[str, Path, str]:
    """Return ``(kind, path, actual_name)`` for an exact controller name.

    Joystick nodes are preferred because their button/axis numbers are the same
    compact indices typically used by PuddleJoy controller YAML files.
    """

    wanted = _normalise_device_name(device_name)
    if not wanted:
        raise ValueError("the selected controller definition has no device name")

    input_root = Path(input_root)
    sysfs_root = Path(sysfs_root)
    if not input_root.is_dir():
        raise RuntimeError("/dev/input is unavailable")

    seen: List[str] = []
    for path in sorted(input_root.glob("js*")):
        try:
            actual = _js_device_name(path)
        except (OSError, PermissionError):
            continue
        if actual:
            seen.append(actual)
        if _normalise_device_name(actual) == wanted:
            return "js", path, actual

    for path in sorted(input_root.glob("event*")):
        try:
            actual = _event_device_name(path, sysfs_root)
        except (OSError, PermissionError):
            continue
        if actual:
            seen.append(actual)
        if _normalise_device_name(actual) == wanted:
            return "event", path, actual

    available = ", ".join(sorted(set(seen), key=str.casefold))
    suffix = f" Available input devices: {available}." if available else " No readable input controllers were found."
    raise RuntimeError(f"controller {device_name!r} is not connected.{suffix}")


def _mapping_from_controller(controller: Mapping[str, Any], key: str) -> Dict[int, str]:
    raw = controller.get(key) or {}
    if not isinstance(raw, Mapping):
        raise ValueError(f"controller {key} must be a mapping")
    result: Dict[int, str] = {}
    for code, action in raw.items():
        result[int(code)] = str(action)
    return result


def parse_controller_yaml(text: str, controller_index: Any) -> Tuple[Dict[str, Any], int, Dict[str, Any]]:
    try:
        index = int(controller_index)
    except (TypeError, ValueError) as exc:
        raise ValueError("controller_index must be an integer") from exc

    document = yaml.safe_load(str(text or "")) or {}
    if not isinstance(document, dict):
        raise ValueError("controller YAML root must be a mapping")
    controllers = document.get("controllers") or []
    if not isinstance(controllers, list):
        raise ValueError("controller YAML 'controllers' must be a list")
    if index < 0 or index >= len(controllers):
        raise ValueError("the selected controller definition no longer exists")
    controller = controllers[index]
    if not isinstance(controller, dict):
        raise ValueError(f"controllers[{index}] must be a mapping")
    device = str(controller.get("device") or "").strip()
    if not device:
        raise ValueError(f"controllers[{index}] is missing device")
    _mapping_from_controller(controller, "buttons")
    _mapping_from_controller(controller, "axes")
    return document, index, controller


def _mapping_key(node: MappingNode, name: str) -> Tuple[int, ScalarNode, Any] | None:
    for position, (key_node, value_node) in enumerate(node.value):
        if isinstance(key_node, ScalarNode) and str(key_node.value) == name:
            return position, key_node, value_node
    return None


def _controller_nodes(text: str, controller_index: int) -> Tuple[MappingNode, SequenceNode, MappingNode]:
    root = yaml.compose(text)
    if not isinstance(root, MappingNode):
        raise ValueError("controller YAML root must be a mapping")
    controllers_entry = _mapping_key(root, "controllers")
    if controllers_entry is None or not isinstance(controllers_entry[2], SequenceNode):
        raise ValueError("controller YAML 'controllers' must be a list")
    sequence = controllers_entry[2]
    if controller_index < 0 or controller_index >= len(sequence.value):
        raise ValueError("the selected controller definition no longer exists")
    controller_node = sequence.value[controller_index]
    if not isinstance(controller_node, MappingNode):
        raise ValueError(f"controllers[{controller_index}] must be a mapping")
    return root, sequence, controller_node


def _line_end(text: str, index: int) -> int:
    found = text.find("\n", max(0, int(index)))
    return len(text) if found < 0 else found + 1


def _quoted_yaml_string(value: str) -> str:
    # JSON strings are valid YAML scalars and make button/action labels
    # containing punctuation unambiguous.
    return json.dumps(str(value), ensure_ascii=False)


def update_controller_mapping_yaml(
    text: str,
    *,
    controller_index: Any,
    kind: str,
    code: Any,
    action: str,
) -> str:
    """Update one ``buttons`` or ``axes`` entry while retaining YAML comments."""

    _document, index, _controller = parse_controller_yaml(text, controller_index)
    section = "buttons" if str(kind).strip().lower() == "button" else "axes" if str(kind).strip().lower() == "axis" else ""
    if not section:
        raise ValueError("mapping kind must be 'button' or 'axis'")
    try:
        raw_code = int(code)
    except (TypeError, ValueError) as exc:
        raise ValueError("controller input code must be an integer") from exc
    label = str(action or "").strip()
    if not label:
        raise ValueError("action name may not be empty")

    _root, _sequence, controller_node = _controller_nodes(text, index)
    section_entry = _mapping_key(controller_node, section)
    rendered = _quoted_yaml_string(label)

    if section_entry is not None:
        position, section_key, section_value = section_entry
        if isinstance(section_value, MappingNode):
            for key_node, value_node in section_value.value:
                try:
                    key_value = int(key_node.value) if isinstance(key_node, ScalarNode) else None
                except (TypeError, ValueError):
                    key_value = None
                if key_value == raw_code:
                    return text[: value_node.start_mark.index] + rendered + text[value_node.end_mark.index :]

            if section_value.flow_style:
                controller = yaml.safe_load(text)["controllers"][index]
                updated = dict(controller.get(section) or {})
                updated[raw_code] = label
                flow = "{" + ", ".join(
                    f"{int(key)}: {_quoted_yaml_string(str(value))}"
                    for key, value in sorted(updated.items(), key=lambda item: int(item[0]))
                ) + "}"
                return text[: section_value.start_mark.index] + flow + text[section_value.end_mark.index :]

            if section_value.value:
                child_indent = section_value.value[0][0].start_mark.column
                last_value = section_value.value[-1][1]
                insert_at = _line_end(text, last_value.end_mark.index)
            else:
                child_indent = section_key.start_mark.column + 2
                insert_at = _line_end(text, section_key.end_mark.index)
            addition = " " * child_indent + f"{raw_code}: {rendered}\n"
            return text[:insert_at] + addition + text[insert_at:]

        # ``buttons:`` with an empty/null value.
        child_indent = section_key.start_mark.column + 2
        replacement = f"\n{' ' * child_indent}{raw_code}: {rendered}"
        return text[: section_value.start_mark.index] + replacement + text[section_value.end_mark.index :]

    # Section absent: append it after the last field in this controller item.
    existing_keys = [pair[0] for pair in controller_node.value if isinstance(pair[0], ScalarNode)]
    field_indent = existing_keys[0].start_mark.column if existing_keys else controller_node.start_mark.column
    if controller_node.value:
        insert_at = _line_end(text, controller_node.value[-1][1].end_mark.index)
    else:
        insert_at = _line_end(text, controller_node.start_mark.index)
    addition = (
        " " * field_indent
        + f"{section}:\n"
        + " " * (field_indent + 2)
        + f"{raw_code}: {rendered}\n"
    )
    return text[:insert_at] + addition + text[insert_at:]


@dataclass(frozen=True)
class ControllerDevice:
    kind: str
    path: Path
    name: str


@dataclass
class _VirtualControllerSource:
    name: str
    path: str
    axis_codes: set[int]
    axes: Dict[int, int]
    subscribers: Dict[int, Deque[Tuple[str, int, int]]]


class VirtualControllerSubscription:
    """One non-destructive subscription to an in-process controller stream."""

    def __init__(
        self,
        hub: "InteractiveControllerEventHub",
        *,
        key: str,
        token: int,
        name: str,
        path: str,
        initial_axes: Mapping[int, int],
    ):
        self._hub = hub
        self._key = str(key)
        self._token = int(token)
        self.name = str(name)
        self.path = str(path)
        self.initial_axes = {int(code): int(value) for code, value in initial_axes.items()}
        self.closed = False

    def drain(self) -> List[Tuple[str, int, int]]:
        if self.closed:
            raise RuntimeError("virtual controller stream is closed")
        return self._hub._drain(self._key, self._token)

    def close(self) -> None:
        if self.closed:
            return
        self.closed = True
        self._hub._disconnect(self._key, self._token)


class InteractiveControllerEventHub:
    """Fan out virtual-controller events without opening their FIFO/device.

    ``PuddleDuckStick`` is produced by :mod:`broadcast_state` itself.  Depending
    on the host, it may be exposed through ``/dev/uinput`` or only through a
    named FIFO.  Opening that FIFO from the interactive editor would steal
    events from RLWalk because a FIFO is not a broadcast transport.  This hub
    taps the producer before either backend and gives the editor an independent
    in-process subscription.
    """

    QUEUE_MAX = 512

    def __init__(self):
        self._lock = threading.RLock()
        self._sources: Dict[str, _VirtualControllerSource] = {}
        self._next_token = 1

    def register(
        self,
        device_name: str,
        *,
        path: str = "broadcast_state",
        axis_codes: Iterable[int] = (),
    ) -> None:
        key = _normalise_device_name(device_name)
        if not key:
            raise ValueError("virtual controller device name may not be empty")
        with self._lock:
            source = self._sources.get(key)
            if source is None:
                self._sources[key] = _VirtualControllerSource(
                    name=str(device_name).strip(),
                    path=str(path or "broadcast_state"),
                    axis_codes={int(code) for code in axis_codes},
                    axes={},
                    subscribers={},
                )
                return
            source.name = str(device_name).strip() or source.name
            source.path = str(path or source.path)
            source.axis_codes.update(int(code) for code in axis_codes)

    def connect(self, device_name: str) -> Optional[VirtualControllerSubscription]:
        key = _normalise_device_name(device_name)
        with self._lock:
            source = self._sources.get(key)
            if source is None:
                return None
            token = self._next_token
            self._next_token += 1
            source.subscribers[token] = deque(maxlen=self.QUEUE_MAX)
            # Only seed axes for which the producer has observed a real value.
            # Treating an unknown pot/slider as zero would make its first SBUS
            # report look like an operator movement and could select the wrong
            # input immediately after opening the editor.
            initial_axes = {code: int(value) for code, value in source.axes.items()}
            return VirtualControllerSubscription(
                self,
                key=key,
                token=token,
                name=source.name,
                path=source.path,
                initial_axes=initial_axes,
            )

    def publish_evdev(self, device_name: str, event_type: int, code: int, value: int) -> bool:
        if int(event_type) == EV_ABS:
            kind = "axis"
        elif int(event_type) == EV_KEY:
            kind = "button"
        else:
            return False

        key = _normalise_device_name(device_name)
        item = (kind, int(code), int(value))
        with self._lock:
            source = self._sources.get(key)
            if source is None:
                return False
            if kind == "axis":
                source.axis_codes.add(int(code))
                source.axes[int(code)] = int(value)
            for events in source.subscribers.values():
                events.append(item)
        return True

    def _drain(self, key: str, token: int) -> List[Tuple[str, int, int]]:
        with self._lock:
            source = self._sources.get(str(key))
            events = source.subscribers.get(int(token)) if source is not None else None
            if events is None:
                raise RuntimeError("virtual controller stream disconnected")
            out = list(events)
            events.clear()
            return out

    def _disconnect(self, key: str, token: int) -> None:
        with self._lock:
            source = self._sources.get(str(key))
            if source is not None:
                source.subscribers.pop(int(token), None)


class InteractiveControllerSession:
    """One physical or in-process controller mapping-capture session."""

    AXIS_TRIGGER = 0.35
    AXIS_RELEASE = 0.15
    AXIS_QUIET_S = 0.12
    AXIS_WINDOW_S = 0.50

    def __init__(
        self,
        *,
        session_id: str,
        device: ControllerDevice,
        fd: Optional[int],
        filename: str,
        controller_index: int,
        buttons: Mapping[int, str],
        axes: Mapping[int, str],
        virtual: Optional[VirtualControllerSubscription] = None,
        clock: Callable[[], float] = time.monotonic,
    ):
        self.session_id = session_id
        self.device = device
        self.fd = int(fd) if fd is not None else None
        self.virtual = virtual
        if self.fd is None and self.virtual is None:
            raise ValueError("interactive controller session requires a device or virtual stream")
        self.filename = str(filename or "")
        self.controller_index = int(controller_index)
        self.buttons = {int(k): str(v) for k, v in buttons.items()}
        self.axes = {int(k): str(v) for k, v in axes.items()}
        self.clock = clock
        self.created_at = self.clock()
        self.last_access = self.created_at
        self.closed = False
        self._lock = threading.RLock()
        self._buffer = b""
        self._events: Deque[Dict[str, Any]] = deque(maxlen=96)
        self._seq = 0
        self._axis_baseline: Dict[int, int] = {}
        self._axis_min: Dict[int, int] = {}
        self._axis_max: Dict[int, int] = {}
        self._axis_active: set[int] = set()
        self._axis_scores: Dict[int, float] = {}
        self._axis_values: Dict[int, int] = {}
        self._axis_started: Optional[float] = None
        self._axis_last_motion: Optional[float] = None
        self._axis_blocked = False
        if self.device.kind == "event":
            self._seed_event_axes(self.axes.keys())
        elif self.virtual is not None:
            self._seed_virtual_axes(self.virtual.initial_axes)

    def _seed_event_axes(self, codes: Iterable[int]) -> None:
        if self.fd is None:
            return
        for code in codes:
            buf = bytearray(_ABSINFO.size)
            try:
                fcntl.ioctl(self.fd, _EVIOCGABS(int(code)), buf, True)
                value, amin, amax, _fuzz, _flat, _resolution = _ABSINFO.unpack(buf)
            except OSError:
                continue
            self._axis_baseline[int(code)] = int(value)
            self._axis_values[int(code)] = int(value)
            self._axis_min[int(code)] = int(amin)
            self._axis_max[int(code)] = int(amax)

    def _seed_virtual_axes(self, values: Mapping[int, int]) -> None:
        for code, raw_value in values.items():
            code = int(code)
            value = int(raw_value)
            self._axis_baseline[code] = value
            self._axis_values[code] = value
            self._axis_min[code] = -32768
            self._axis_max[code] = 32767

    def close(self) -> None:
        with self._lock:
            if self.closed:
                return
            self.closed = True
            if self.virtual is not None:
                self.virtual.close()
            if self.fd is not None:
                try:
                    os.close(self.fd)
                except OSError:
                    pass

    def update_mapping(self, kind: str, code: int, action: str) -> None:
        with self._lock:
            target = self.buttons if kind == "button" else self.axes
            target[int(code)] = str(action)

    def _emit(self, kind: str, code: int, value: int | float, *, strength: Optional[float] = None) -> None:
        self._seq += 1
        mapping = self.buttons if kind == "button" else self.axes
        event = {
            "seq": self._seq,
            "kind": kind,
            "code": int(code),
            "value": value,
            "action": str(mapping.get(int(code), "")),
        }
        if strength is not None:
            event["strength"] = round(float(strength), 4)
        self._events.append(event)

    def _axis_strength(self, code: int, value: int) -> float:
        baseline = self._axis_baseline.get(code)
        if baseline is None:
            self._axis_baseline[code] = int(value)
            self._axis_values[code] = int(value)
            if self.device.kind == "js":
                self._axis_min.setdefault(code, -32767)
                self._axis_max.setdefault(code, 32767)
            return 0.0
        amin = self._axis_min.get(code, -32767)
        amax = self._axis_max.get(code, 32767)
        span = max(abs(int(amax) - baseline), abs(int(amin) - baseline), 1)
        return min(1.0, abs(int(value) - baseline) / float(span))

    def _handle_axis(self, code: int, value: int, now: float, *, initial: bool = False) -> None:
        code = int(code)
        value = int(value)
        if initial:
            self._axis_baseline[code] = value
            self._axis_values[code] = value
            self._axis_min.setdefault(code, -32767)
            self._axis_max.setdefault(code, 32767)
            return

        strength = self._axis_strength(code, value)
        self._axis_values[code] = value
        if strength <= self.AXIS_RELEASE:
            self._axis_active.discard(code)
            if self._axis_blocked and not self._axis_active:
                self._axis_blocked = False
            return

        if strength < self.AXIS_TRIGGER:
            return
        self._axis_active.add(code)
        if self._axis_blocked:
            return
        if self._axis_started is None:
            self._axis_started = now
            self._axis_scores = {}
        self._axis_scores[code] = max(strength, self._axis_scores.get(code, 0.0))
        self._axis_last_motion = now

    def _finalize_axis(self, now: float) -> None:
        if self._axis_started is None or not self._axis_scores:
            return
        last = self._axis_last_motion if self._axis_last_motion is not None else self._axis_started
        if (now - last) < self.AXIS_QUIET_S and (now - self._axis_started) < self.AXIS_WINDOW_S:
            return
        code, strength = max(self._axis_scores.items(), key=lambda item: (item[1], -item[0]))
        self._emit("axis", code, self._axis_values.get(code, 0), strength=strength)
        self._axis_started = None
        self._axis_last_motion = None
        self._axis_scores = {}
        self._axis_blocked = bool(self._axis_active)

    def _consume_js(self, data: bytes, now: float) -> None:
        self._buffer += data
        while len(self._buffer) >= _JS_EVENT.size:
            chunk, self._buffer = self._buffer[: _JS_EVENT.size], self._buffer[_JS_EVENT.size :]
            _timestamp, value, event_type, number = _JS_EVENT.unpack(chunk)
            initial = bool(event_type & JS_EVENT_INIT)
            event_type &= ~JS_EVENT_INIT
            if event_type & JS_EVENT_BUTTON:
                if not initial and int(value):
                    self._emit("button", int(number), int(value))
            elif event_type & JS_EVENT_AXIS:
                self._handle_axis(int(number), int(value), now, initial=initial)

    def _consume_event(self, data: bytes, now: float) -> None:
        self._buffer += data
        while len(self._buffer) >= _INPUT_EVENT.size:
            chunk, self._buffer = self._buffer[: _INPUT_EVENT.size], self._buffer[_INPUT_EVENT.size :]
            _sec, _usec, event_type, code, value = _INPUT_EVENT.unpack(chunk)
            if event_type == EV_KEY and int(value):
                self._emit("button", int(code), int(value))
            elif event_type == EV_ABS:
                self._handle_axis(int(code), int(value), now)

    def _read_available(self, now: float) -> None:
        if self.virtual is not None:
            for kind, code, value in self.virtual.drain():
                if kind == "button":
                    if int(value):
                        self._emit("button", int(code), int(value))
                elif kind == "axis":
                    self._handle_axis(int(code), int(value), now)
            return

        if self.fd is None:
            raise RuntimeError("interactive controller device is unavailable")
        while True:
            try:
                data = os.read(self.fd, 4096)
            except BlockingIOError:
                break
            except OSError as exc:
                self.close()
                raise RuntimeError(f"controller disconnected: {exc}") from exc
            if not data:
                self.close()
                raise RuntimeError("controller disconnected")
            if self.device.kind == "js":
                self._consume_js(data, now)
            else:
                self._consume_event(data, now)
            if len(data) < 4096:
                break

    def poll(self, after: Any = 0) -> Dict[str, Any]:
        try:
            after_seq = max(0, int(after or 0))
        except (TypeError, ValueError):
            after_seq = 0
        with self._lock:
            if self.closed:
                raise RuntimeError("interactive controller session is closed")
            now = self.clock()
            self.last_access = now
            self._read_available(now)
            self._finalize_axis(now)
            return {
                "ok": True,
                "session": self.session_id,
                "events": [dict(item) for item in self._events if int(item["seq"]) > after_seq],
                "last_seq": self._seq,
                "connected": not self.closed,
            }

    def snapshot(self) -> Dict[str, Any]:
        if self.device.kind == "virtual":
            message = f"Connected to {self.device.name} through the in-process controller stream"
        else:
            message = f"Connected to {self.device.name} at {self.device.path}"
        return {
            "ok": True,
            "session": self.session_id,
            "filename": self.filename,
            "controller_index": self.controller_index,
            "device": self.device.name,
            "path": str(self.device.path),
            "input_kind": self.device.kind,
            "buttons": dict(sorted(self.buttons.items())),
            "axes": dict(sorted(self.axes.items())),
            "message": message,
        }


class InteractiveControllerManager:
    """Own the currently active interactive mapping session."""

    SESSION_MAX_IDLE_S = 300.0

    def __init__(
        self,
        *,
        input_root: Path | str = "/dev/input",
        sysfs_root: Path | str = "/sys/class/input",
        locator: Callable[..., Tuple[str, Path, str]] = find_controller_device,
        opener: Callable[[Path], int] | None = None,
        virtual_hub: Optional[InteractiveControllerEventHub] = None,
        clock: Callable[[], float] = time.monotonic,
    ):
        self.input_root = Path(input_root)
        self.sysfs_root = Path(sysfs_root)
        self.locator = locator
        self.opener = opener or (lambda path: os.open(path, os.O_RDONLY | os.O_NONBLOCK))
        self.virtual_hub = virtual_hub
        self.clock = clock
        self._lock = threading.RLock()
        self._session: Optional[InteractiveControllerSession] = None

    def _close_locked(self) -> None:
        if self._session is not None:
            self._session.close()
            self._session = None

    def close(self) -> None:
        with self._lock:
            self._close_locked()

    def start(self, *, filename: str, text: str, controller_index: Any) -> Dict[str, Any]:
        # A new connection attempt replaces the previous capture immediately.
        # This avoids leaving an unread controller descriptor behind when the
        # operator switches definitions and the newly selected device is absent.
        with self._lock:
            self._close_locked()
        _document, index, controller = parse_controller_yaml(text, controller_index)
        device_name = str(controller.get("device") or "").strip()
        buttons = _mapping_from_controller(controller, "buttons")
        axes = _mapping_from_controller(controller, "axes")

        virtual = self.virtual_hub.connect(device_name) if self.virtual_hub is not None else None
        if virtual is not None:
            try:
                session = InteractiveControllerSession(
                    session_id=secrets.token_urlsafe(18),
                    device=ControllerDevice("virtual", Path(virtual.path), virtual.name),
                    fd=None,
                    virtual=virtual,
                    filename=filename,
                    controller_index=index,
                    buttons=buttons,
                    axes=axes,
                    clock=self.clock,
                )
            except Exception:
                virtual.close()
                raise
            with self._lock:
                self._close_locked()
                self._session = session
            return session.snapshot()

        kind, path, actual_name = self.locator(
            device_name,
            input_root=self.input_root,
            sysfs_root=self.sysfs_root,
        )
        try:
            fd = self.opener(Path(path))
        except PermissionError as exc:
            raise RuntimeError(f"permission denied opening controller {path}") from exc
        except OSError as exc:
            raise RuntimeError(f"unable to open controller {path}: {exc}") from exc

        session = InteractiveControllerSession(
            session_id=secrets.token_urlsafe(18),
            device=ControllerDevice(str(kind), Path(path), str(actual_name or device_name)),
            fd=fd,
            filename=filename,
            controller_index=index,
            buttons=buttons,
            axes=axes,
            clock=self.clock,
        )
        with self._lock:
            self._close_locked()
            self._session = session
        return session.snapshot()

    def _get_locked(self, session_id: Any) -> InteractiveControllerSession:
        session = self._session
        if session is None or not secrets.compare_digest(str(session.session_id), str(session_id or "")):
            raise RuntimeError("interactive controller session is no longer active")
        if self.clock() - session.last_access > self.SESSION_MAX_IDLE_S:
            self._close_locked()
            raise RuntimeError("interactive controller session expired")
        return session

    def poll(self, session_id: Any, after: Any = 0) -> Dict[str, Any]:
        with self._lock:
            session = self._get_locked(session_id)
            return session.poll(after)

    def apply(
        self,
        *,
        session_id: Any,
        text: str,
        controller_index: Any,
        kind: str,
        code: Any,
        action: str,
    ) -> Dict[str, Any]:
        with self._lock:
            session = self._get_locked(session_id)
            if int(controller_index) != session.controller_index:
                raise ValueError("the selected controller changed; reconnect the interactive editor")
            updated = update_controller_mapping_yaml(
                text,
                controller_index=controller_index,
                kind=kind,
                code=code,
                action=action,
            )
            session.update_mapping(str(kind).strip().lower(), int(code), str(action).strip())
            return {
                "ok": True,
                "yaml": updated,
                "session": session.session_id,
                "controller_index": session.controller_index,
                "kind": str(kind).strip().lower(),
                "code": int(code),
                "action": str(action).strip(),
            }

    def stop(self, session_id: Any = "") -> Dict[str, Any]:
        with self._lock:
            if self._session is None:
                return {"ok": True, "stopped": False}
            if session_id and not secrets.compare_digest(str(self._session.session_id), str(session_id)):
                raise RuntimeError("interactive controller session is no longer active")
            self._close_locked()
            return {"ok": True, "stopped": True}
